from review import card,save,DATE

def ref(i,title,authors,year,url,locator,**extra):return dict(id=i,title=title,authors=authors,year=year,url=url,locator=locator,**extra)
def b(title,text,citation=None):
 d=dict(title=title,text=text)
 if citation:d['citation']=citation
 return d

def finish(i,c,changes,notes,refs,issue=None,extra=()):
 changes.update(references=refs,question_type='yes_no',model_self_contained=not bool(issue),requires_context=bool(issue),importance=dict(score=c['importance']['score'],method='editorial',assessed_on=DATE,reason=changes.pop('importance_reason')+' Existing score retained.'))
 if issue:changes['statement_review']=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=notes)
 save(i,changes,notes=notes,checked_sources=[r['url'] for r in refs]+list(extra),state='improved_unfinished' if issue else 'revised')

i='TCS-2815';_,c=card(i);refs=c['references'];refs[0]['locator']='MFCS 2022, article 4: Definition 10 and Section 3.2, pp. 4:7–4:8; Section 6, p. 4:17; reference [7]. The finite-state CSG and continuous-state neuro-symbolic extensions are different models.'
refs.append(ref('mixed2014','Mixed Nash Equilibria in Concurrent Terminal-Reward Games','Patricia Bouyer; Nicolas Markey; Daniel Stan',2014,'https://doi.org/10.4230/LIPIcs.FSTTCS.2014.351','Definitions 2–3 and the observation-only-state-history remark, pp. 353–354; Corollaries 14 and 16, p. 361; remaining two-player question, p. 362.'))
issue='The survey does not isolate one payoff family and player-count restriction for its brief infinite-horizon existence question. Its general CSG strategies observe states and joint actions, whereas reference [7] permits only state-history observation. The survey also focuses on equilibrium from every state, while the underlying existence discussion includes ordinary Nash equilibrium from an initial state. The intended objective class, observation convention and equilibrium requirement must be reconciled before one universal proposition can be certified. The continuous-state neuro-symbolic extension must not be substituted silently.'
finish(i,c,dict(title='Exact Nash equilibria for infinite-horizon concurrent stochastic games',formal='Do all concurrent stochastic games in the infinite-horizon objective class intended by the MFCS 2022 survey admit an exact Nash equilibrium? The survey contrasts finite-horizon analysis with this existence question, but the excerpt and its cited reference do not determine a single common payoff, observation and equilibrium model. The quantifier “all” must therefore remain attached to a model still requiring specification; it is not a claim about every stochastic game with an arbitrary real-valued payoff.',definitions='The survey’s finite-state concurrent stochastic game has a finite set S of states, an initial state s₀, finitely many players i∈{1,…,m}, a finite nonempty action set Aᵢ(s) at each state, and a transition distribution δ(s,a₁,…,aₘ) on S. Players act simultaneously; the next state is drawn from this distribution. A behavioral strategy assigns a distribution on available actions to each finite observed history; players randomize independently. In Definition 10 the history includes past states and joint actions. There is no predetermined terminal time. Each player maximizes the expectation of a specified measurable payoff Xᵢ on infinite plays, under conditions ensuring the expectation is defined. A profile σ is an exact Nash equilibrium from s₀ if Eσ,s₀[Xᵢ]≥E(τᵢ,σ₋ᵢ),s₀[Xᵢ] for every player i and every admissible unilateral strategy τᵢ. An ε-equilibrium allows the right side to exceed the left by at most ε; existence for every ε>0 does not assert existence at ε=0. Requiring the equilibrium inequality from all states, or after every history, is an additional requirement. In the cited terminal-reward model, an absorbing terminal state carries each player’s reward and a nonterminating play pays zero; terminal-reachability rewards are restricted to {0,1}. These conventions describe the sources, not a recovered choice between their models.',answer_criterion='After recovering the intended payoff, observation and equilibrium restrictions, prove that every game in that class has an exact equilibrium, or refute that universal statement by a game in the same class with no such equilibrium. An ε-equilibrium theorem, a finite-horizon theorem, or an undecidability result for a constrained equilibrium search task does not by itself settle that existence statement.',context_blocks=[b('Finite state does not mean finite play','Even a game with finitely many states can continue forever. Payoffs may distinguish eventual termination from perpetual play, so the equilibrium question changes when an imposed time limit is removed.','primary'),b('The cited result is more specific than the excerpt','The 2014 paper proves undecidability of constrained equilibrium existence for three-player terminal-reachability games. It also proves undecidability of unconstrained existence for terminal rewards that may be negative. These are precise algorithmic statements, not a generic declaration that equilibrium existence is open.','mixed2014'),b('Information affects deviations','The 2014 model observes only visited states, not the action profile producing a transition. The survey’s definition includes joint actions in histories. Existence and hardness results cannot be transferred between those strategy spaces without justification.','mixed2014'),b('A narrower existence question remains in the cited conclusion','The 2014 conclusion explicitly retains the two-player nonnegative-terminal-reward existence question and discusses an earlier incorrect counterexample. This explains why the citation requires careful scoping; it does not select that restricted question on behalf of the survey.','mixed2014'),b('Remaining formulation issue',issue)],why='Exact equilibrium existence determines whether an infinite-duration multi-agent model has stable behavior at all, before verification can optimize or synthesize such behavior.',importance_reason='Addresses the mathematical foundation of equilibrium-based verification, with objective and information assumptions essential to the result.',progress=[dict(date='2014',text='The cited paper separates constrained three-player undecidability, signed terminal-reward existence undecidability, and an unresolved two-player nonnegative-reward existence question.',citation='mixed2014'),dict(date='2022',text='The survey repeats an infinite-horizon existence question while using approximate equilibria for its analysis; its brief wording does not fix the missing scope.',citation='primary')],status='uncertain',status_note='Read the survey’s game/strategy definitions and the full cited 2014 paper, and searched later equilibrium-existence literature through 12 September 2026. No single currently open proposition matching all these model choices has been established by this review.',review_note='Replaced the truncated excerpt with a scoped existence question and explicit Nash inequality. Preserved the unresolved model choices, including the different observation conventions, rather than declaring an unrelated undecidability theorem to be its resolution.',working_summary=dict(sentences=['The question concerns stable strategic behavior in games with simultaneous actions and no fixed time horizon.','Exact Nash equilibrium forbids any profitable unilateral change of strategy.','Finite-horizon and approximate equilibrium results do not automatically imply exact infinite-horizon existence.','The survey and its underlying citation use different information conventions and discuss several payoff classes.','Those choices must be reconciled before this card can specify one universal existence theorem.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','mixed2014'])),['Recovered the finite-state game and exact equilibrium definitions.','Read the underlying existence and undecidability results.','Identified payoff, observation and equilibrium-scope choices rather than inventing a replacement.'],refs,issue)

i='TCS-2816';_,c=card(i);refs=c['references'];refs[0]['locator']='OPODIS 2022, article 4: Section 2 (system model and exact FIFO semantics), results table and conclusion on p. 4:18.'
refs.append(ref('polylog2023','A Wait-free Queue with Polylogarithmic Step Complexity','Hossein Naderibeni; Eric Ruppert',2023,'https://doi.org/10.1145/3583668.3594565','PODC 2023, pp. 124–134; arXiv:2305.07229, Section 1 (word assumptions and related work), Theorem 22 and Section 7.',pdf_url='https://arxiv.org/pdf/2305.07229'))
issue='The target O(log n) bound is clear, but Section 2 does not impose a precise upper bound on the bits stored in one primitive-accessible register or specify a separate local-computation cost. This is substantive: the 2023 follow-up reports an O(log n)-operation universal construction when words hold Ω(n log n) bits, while its own queue uses words sized for an item/pointer and operation count. A completed benchmark must fix the intended word-size and primitive/local-cost convention; unrestricted unit-cost wide words cannot be treated as equivalent to ordinary word-sized CAS.'
finish(i,c,dict(title='An unrestricted exact wait-free FIFO queue in O(log n) steps',formal='Is there a deterministic implementation of an exact, linearizable FIFO queue for n≥2 asynchronous processes such that every enqueue and dequeue finishes within C log₂(n+1) of its own steps, for one constant C independent of the execution, the queue length and n, with every process allowed to perform either operation? The guarantee is worst-case for each operation under arbitrary scheduling and crashes. The intended bound on one memory word, which affects whether this is still open, is missing from the source’s system model.',definitions='There are n sequential processes with distinct identifiers, using shared memory; a process can stop permanently at any time. A process invokes a new queue operation only after its previous one returns. Initially the queue is empty. Enqueue(v) appends a value v; Dequeue() removes and returns the earliest remaining value, or returns a distinguished EMPTY value if none remains. Linearizability means that completed operations, together with any pending operations needed to complete the history, admit a legal sequential FIFO ordering respecting real-time precedence: an operation returning before another is invoked must come first. Wait-freedom requires each operation of a process that continues taking steps to finish after boundedly many of that process’s steps, regardless of the others. The source counts atomic base-object accesses and high-level invocation/response events. Base primitives include atomic read/write, fetch-and-increment (return the old integer and add one), and compare-and-swap (replace a value only if it equals the supplied expected value). Restricted max-register uses in the source are implemented by constantly many CAS primitives; they do not provide arbitrary uncharged computation. Shared memory may grow with the execution. The requested step bound must not depend on the current queue length q or the number of earlier operations. The source has not specified the bit capacity of a primitive-accessible word or how local computation is charged.',answer_criterion='Fix the intended memory-word and cost convention, then prove or refute existence of one exact wait-free linearizable implementation with the stated per-operation worst-case bound. A correct construction must handle arbitrary well-formed histories with all n processes both enqueuing and dequeuing. An amortized or expected bound, a bound depending on q, a fixed limit on dequeuers, or relaxed multiplicity semantics does not establish this target.',context_blocks=[b('Ordering and progress are simultaneous requirements','Exact FIFO semantics must hold even when operations overlap. Wait-freedom additionally prevents one unlucky process from being delayed indefinitely by repeated interference.','primary'),b('The number of dequeuers is unrestricted','The source’s exact queue has O(log n) enqueue complexity and O(k log n) dequeue complexity when at most k processes dequeue. Its logarithmic result with multiplicity changes the allowed outputs, so neither supplies the unrestricted exact target.','primary'),b('The later queue substantially narrows the gap','The PODC 2023 construction uses single-word CAS and has O(log n) enqueue and O(log² n+log q) dequeue complexity. Its version with bounded retained space instead has an amortized O(log n log(n+q)) bound. These guarantees still differ from worst-case O(log n) independent of q.','polylog2023'),b('Word size changes the answer','The same follow-up explains that a universal construction already gives O(log n) operations with words of Ω(n log n) bits. Counting such a word as one step is a materially stronger convention than the reasonably sized words used by its queue.','polylog2023'),b('Remaining formulation issue',issue)],why='Tests whether exact ordering and individual progress can coexist with logarithmic worst-case operation latency under unrestricted concurrent access.',importance_reason='A basic boundary for concurrent data structures, relating strict FIFO correctness, wait-free progress and worst-case latency.',progress=[dict(date='2022',text='The source achieves O(log n) enqueue and O(k log n) dequeue steps for k dequeuers and asks for logarithmic worst-case complexity without that restriction.',citation='primary'),dict(date='2023',text='The PODC follow-up achieves O(log n) enqueues and O(log² n+log q) dequeues using single-word CAS; its introduction also identifies the wide-word universal-construction caveat.',citation='polylog2023')],status='source_open',status_note='Checked the full OPODIS 2022 and PODC 2023 papers and searched subsequent work through 12 September 2026. No matching ordinary-word, queue-length-independent O(log n) worst-case result was located. The original question still needs a precise word/cost convention before openness can be certified.',review_note='Restored the omitted unrestricted-process condition and separated worst-case, amortized, queue-length-dependent and wide-word guarantees.',working_summary=dict(sentences=['All n asynchronous processes must be allowed to enqueue and dequeue from the same exact FIFO queue.','Every operation should complete in O(log n) of its own steps despite arbitrary interference or crashes.','The bound is worst-case and independent of queue length.','A later queue obtains polylogarithmic bounds but retains an extra logarithm and queue-length dependence for dequeues.','The memory-word convention must be fixed because much wider words already permit logarithmic universal constructions.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','polylog2023'])),['Defined exact FIFO, linearizability, wait-freedom and per-operation costs.','Checked the 2023 polylogarithmic follow-up.','Recorded the wide-word ambiguity instead of falsely certifying unrestricted model openness.'],refs,issue,extra=['https://doi.org/10.4230/LIPIcs.OPODIS.2023.17'])

i='TCS-2821';_,c=card(i);refs=c['references'];refs[0]['locator']='STACS 2022, article 19: Section 2 (subshifts), Section 6, pp. 19:13–19:14 (centers conjecture and its quantifier caveats).'
refs.append(ref('authorpage','Aperiodic points in subshifts — research description','Benjamin Hellouin de Menibus',None,'https://perso.lisn.upsaclay.fr/hellouin/index_en.html','Aperiodic points in subshifts section, publications C5/C6; checked 12 September 2026. The page identifies the three-dimensional case as open; it does not give a formal centers bound.'))
issue='The source does not define the concentric zones, a quantitative radius bound, or the effectivity/uniformity required of that bound. Merely saying that each nonzero period is broken somewhere within some finite distance from a chosen center follows from aperiodicity itself. Even dependence only on vector length, alphabet size and forbidden-pattern size needs a substantive bound or effectiveness condition to express the intended stronger structural principle. No computable radius function or annulus geometry is invented here.'
finish(i,c,dict(title='Centers of aperiodicity in three-dimensional shifts of finite type',formal='Does every shift of finite type X⊆Σ^{ℤ³} that contains at least one aperiodic configuration contain an aperiodic configuration with the “center of aperiodicity” property proposed by Callard and Hellouin de Menibus? The source describes concentric zones witnessing broken periods at distances controlled by the period vector’s length, the alphabet size and the largest forbidden-pattern size. It does not state the precise zone/radius requirement. The desired configuration may differ from the initially given one; the conjecture is not a claim about every aperiodic configuration or its orbit closure.',definitions='Σ is a finite nonempty alphabet. A configuration is a map x:ℤ³→Σ. A finite pattern assigns symbols to a finite set of lattice sites. Given a finite list F of forbidden patterns, the shift of finite type X consists of all configurations containing no translate of any pattern in F. Its presentation is finite even though its configurations are infinite. A vector v∈ℤ³ is a period of x if x(u)=x(u+v) for every u∈ℤ³. The configuration is aperiodic if zero is its only period; a witness breaking v≠0 is a site u with x(u)≠x(u+v). Translating a configuration shifts all its coordinates. Its orbit closure consists of limits of such translates, where convergence means eventual agreement on each finite set of sites. A center is intended to organize witnesses for different period lengths in bounded concentric regions around one lattice location. The source’s unspecified radius and region conventions are part of the missing mathematical predicate, not established definitions.',answer_criterion='Recover the quantitative and effective center predicate intended by the source, then prove it for every three-dimensional SFT containing an aperiodic point, or exhibit an SFT that violates it while still containing an aperiodic point. Aperiodicity alone, a theorem only in two dimensions, or a center for one special SFT does not establish the universal structural claim. No result is required for the orbit closure of each prescribed aperiodic point.',context_blocks=[b('Local rules can force global nonperiodicity','A finite forbidden-pattern list defines the entire space of legal infinite configurations. The question asks whether the absence of any translation period must also have a uniformly organized spatial witness in some legal configuration.','primary'),b('The existential configuration matters','The source explicitly warns that in dimension three a center may occur in an aperiodic configuration unrelated to the orbit closure of another aperiodic point. Requiring every such orbit closure to contain a center would strengthen the question.','primary'),b('Dimension three is the unresolved boundary in the source','The paper proves a much higher degree of undecidability for detecting aperiodic points in SFTs of dimension at least four, compared with the two-dimensional result. The author’s research page continues to identify the three-dimensional case as open. This context does not supply the missing center predicate.','authorpage'),b('Remaining formulation issue',issue)],why='Would identify a structural constraint on three-dimensional tiling systems and clarify why detecting nonperiodic behavior may differ so sharply between dimensions.',importance_reason='Links spatial structure in symbolic dynamics with the computability boundary for detecting aperiodic tilings.',progress=[dict(date='2022',text='The paper states the centers conjecture in Section 6, explicitly restricting it to SFTs and allowing the center to lie in a different aperiodic configuration.',citation='primary'),dict(date=DATE,text='The author’s research description still lists the three-dimensional aperiodic-point case as open, but supplies no quantitative formulation of the centers conjecture.',citation='authorpage')],status='source_open',status_note='Checked the complete STACS conclusion, arXiv:2202.07377 version history and the author’s current research description. The centers statement remains underspecified; the current page’s broader open-status statement does not repair it.',review_note='Recovered the intended existential configuration and SFT restriction, defined aperiodicity and orbit closure, and recorded the missing effective quantitative center condition.',working_summary=dict(sentences=['A three-dimensional shift of finite type is an infinite tiling space given by finitely many local prohibitions.','An aperiodic configuration breaks every nonzero translation vector.','The source conjectures that some such configuration organizes these witnesses around a center.','It explicitly permits this configuration to differ from other aperiodic points and their orbit closures.','The geometry and strength of the proposed radius control remain unspecified and are essential to the benchmark.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','authorpage'])),['Defined SFTs, period-breaking witnesses and orbit closure.','Preserved existential configuration and dimension-three SFT scope.','Recorded the missing quantitative/effective center predicate and checked the author’s later status description.'],refs,issue,extra=['https://arxiv.org/abs/2202.07377'])

i='TCS-2824';_,c=card(i);refs=c['references'];refs[0]['year']=2023;refs[0]['locator']='TYPES 2022 proceedings published 2023, article 2: Definitions 1–2, pp. 2:3–2:4; Section 7, p. 2:26, syntactic equivalence conjecture. The constructive introduction rule, not the classical one, defines the target.'
finish(i,c,dict(title='When does truth-table reconstruction preserve an intuitionistic connective?',formal='For every n≥1 and every propositional formula F(p₁,…,pₙ) built from ∧, ∨, → and ¬, suppose that each disjunction subformula P∨Q has both P and Q free of → and ¬, each implication subformula P→Q has P free of → and ¬, and each negation subformula ¬P has P free of → and ¬. Let c_F be a fresh n-ary connective with the constructive truth-table natural-deduction rules below, derived from the classical Boolean truth table of F. Must c_F(A₁,…,Aₙ) and F(A₁,…,Aₙ) be interderivable in intuitionistic logic with those rules, for every substitution of formulas A₁,…,Aₙ? The syntactic restriction is checked on the template F before substitution.',definitions='Formulas are finite syntax trees over propositional variables and the listed connectives; repeated variables are allowed. The restriction “free of → and ¬” means that only variables, ∧ and ∨ occur in that subformula. The Boolean truth table t_F:{0,1}ⁿ→{0,1} evaluates ∧ as conjunction, ∨ as disjunction, → as material implication and ¬ as complement. For a substitution A=(A₁,…,Aₙ), write Φ=c_F(A). Derivations are finite intuitionistic natural-deduction derivations with the usual assumption, conjunction, disjunction, implication and negation rules, including falsity elimination; ¬B has its usual intuitionistic meaning B→⊥. Add the following rule schemata, with Γ a finite context and D any formula. For each row r with t_F(r)=0, from Γ⊢Φ, all premises Γ⊢Aᵢ with rᵢ=1, and all premises Γ,Aⱼ⊢D with rⱼ=0, infer Γ⊢D, discharging the indicated extra assumptions. For each row r with t_F(r)=1, from all Γ⊢Aᵢ with rᵢ=1 and all Γ,Aⱼ⊢Φ with rⱼ=0, infer Γ⊢Φ, again discharging the indicated assumptions. An empty family of premises contributes no requirement. Rule instances may use arbitrary formulas in the extended language; no excluded-middle or classical introduction rule is added. Interderivable means that both Φ⊢F(A) and F(A)⊢Φ have such derivations. This is an exact syntactic equivalence claim with no computational-resource or probability bound.',answer_criterion='Prove both derivability directions for every qualifying formula template and every substitution, or refute the universal statement with a qualifying template for which at least one direction is not derivable in the specified calculus. A mismatch for a template violating the syntactic condition is not a counterexample; classical equivalence alone is insufficient.',context_blocks=[b('A Boolean table can lose constructive information','Formulas with the same two-valued truth table can have different intuitionistic meanings. The question asks when the source’s uniform conversion from a truth table back into proof rules preserves the original constructive connective.','primary'),b('The source gives concrete failures outside the proposed class','For example, its reconstruction of A∨(B→C) has the meaning of B→(A∨C), which is weaker intuitionistically. That template fails the condition because one disjunct contains implication.','primary'),b('The restriction is on sensitive syntactic positions','Both sides of a disjunction must be monotone formulas, and implication antecedents and negated formulas must be monotone. The consequent of an implication is governed by the same condition recursively. Arbitrary substituted formulas are not themselves required to be monotone.','primary'),b('The proof-rule choice matters','Constructive truth-table introduction discharges assumptions while retaining the introduced formula as conclusion. The paper also defines a different classical rule. Using that rule would erase the distinction the conjecture is meant to explain.','primary')],why='Would give a syntactic guarantee that automatic proof-rule generation preserves a defined connective’s intuitionistic meaning, clarifying the expressive limits of truth-table natural deduction.',importance_reason='A structural question about how compositional constructive meaning survives generic generation of proof rules from Boolean data.',progress=[dict(date='2023',text='The TYPES 2022 proceedings paper states the sufficient syntactic condition in its conclusion and supplies the precise constructive rule generator in Definitions 1–2.',citation='primary')],status='source_open',status_note='Read the complete rule generator and conjecture in the published paper and searched later work on truth-table natural deduction through 12 September 2026. No proof or counterexample to this exact syntactic condition was located. The author’s available publications page is dated through 2022 and is not by itself current-status evidence.',review_note='Reconstructed both constructive rule schemata explicitly, retained the condition on both disjuncts, and separated template syntax from arbitrary substitution. The statement concerns the standard four-connective grammar displayed in the source, without adding other connective families.',working_summary=dict(sentences=['The source generates introduction and elimination rules from a connective’s Boolean truth table.','In intuitionistic logic, this reconstruction can change the meaning of a formula built from standard connectives.','The conjecture identifies a sufficient restriction on disjuncts, implication antecedents and negated subformulas.','For every template satisfying it, reconstruction should preserve both directions of derivability under arbitrary substitutions.','A resolution would delineate a class in which truth-table proof-rule generation preserves constructive meaning.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary'])),['Recovered the exact sufficient syntactic condition.','Defined both constructive truth-table rule schemata and intuitionistic interderivability.','Separated template restrictions from substitution and checked later literature.'],refs,extra=['https://www.cs.ru.nl/~herman/pubs.html','https://www.ru.nl/en/people/geuvers-j'])
